'use strict';
const C=Captions,$=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x));
let state={schema:'caption-desk/1',title:"Practice — The editor's promise",cues:copy(C.demo)},selected=0,history=[],limits={cps:20,line:42,min:800},videoURL='',dirty=false;
const key='caption-desk-v1';
const hiddenStyle=document.createElement('style');hiddenStyle.textContent='[hidden]{display:none!important}';document.head.append(hiddenStyle);
document.querySelectorAll('label.button').forEach(label=>{label.tabIndex=0;label.setAttribute('role','button');label.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();label.querySelector('input').click();}};});
function notice(s,error=false){$('notice').textContent=s;$('notice').style.borderColor=error?'#ff9292':'#a0efbf';}
function guard(fn){try{return fn();}catch(e){notice(e.message,true);return null;}}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('saved').textContent='Saved in this browser · export a backup';}catch(e){$('saved').textContent='Browser save unavailable — export a backup';}}
function commit(cues,message){C.validate(cues);history.push(copy(state));if(history.length>30)history.shift();state.cues=cues;selected=Math.min(selected,cues.length-1);dirty=false;save();render();notice(message);}
function discard(){return !dirty||confirm('Discard unsaved changes to this caption?');}
function replace(p,msg){if(!discard())return;if(!confirm('Replace this project? Save a backup first if you need it later. Undo can restore the last project during this session.'))return;history.push(copy(state));if(history.length>30)history.shift();state={schema:'caption-desk/1',...p};selected=0;dirty=false;$('video').pause();$('video').removeAttribute('src');$('video').hidden=true;if(videoURL)URL.revokeObjectURL(videoURL);videoURL='';$('previewEmpty').hidden=false;$('videoName').textContent='Attach the matching local video to check timing.';$('clipStart').value=C.stamp(state.cues[0].start);$('clipEnd').value=C.stamp(Math.max(...state.cues.map(c=>c.end)));$('clipSummary').textContent='Range reset for the new project. Review it before exporting.';save();render();notice(msg);}
function allIssues(){return C.issues(state.cues,limits);}
function queue(){const found=allIssues(),query=$('search').value.toLocaleLowerCase(),only=$('onlyIssues').checked;const parent=$('cues');parent.replaceChildren();state.cues.forEach((c,i)=>{const flags=found.filter(x=>x.index===i);if((only&&!flags.length)||!c.text.toLocaleLowerCase().includes(query))return;const b=document.createElement('button');b.className='cue'+(i===selected?' active':'');b.setAttribute('aria-label','Select caption '+(i+1));let m=document.createElement('span');m.className='meta';m.textContent=String(i+1).padStart(3,'0')+' / '+C.stamp(c.start);let t=document.createElement('span');t.className='words';t.textContent=c.text||'[Empty caption]';b.append(m,t);if(flags.length){let f=document.createElement('span');f.className='badge';f.textContent=flags.length+' review '+(flags.length===1?'item':'items');b.append(f);}b.onclick=()=>{if(!discard())return;selected=i;dirty=false;render();$('scrub').value=c.start;if(videoURL)$('video').currentTime=c.start/1000;preview(c.start);};parent.append(b);});if(!parent.children.length)parent.textContent='No captions match this filter.';}
function render(){
 $('title').value=state.title;$('undo').disabled=!history.length;$('count').textContent=state.cues.length;
 const found=allIssues(),n=new Set(found.map(x=>x.index)).size,end=Math.max(...state.cues.map(x=>x.end));
 $('stats').replaceChildren();for(const [v,label] of [[state.cues.length,'captions'],[C.stamp(end).slice(0,8),'last caption ends'],[n,'captions to review'],[found.filter(x=>x.code==='overlap').length,'overlapping captions']]){const el=document.createElement('div');el.className='stat';const strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=v;span.textContent=label;el.append(strong,span);$('stats').append(el);}
 queue();renderBatch();const c=state.cues[selected];$('editHeading').textContent='Caption '+(selected+1);$('editMeta').textContent=((c.end-c.start)/1000).toFixed(2)+' sec';$('start').value=C.stamp(c.start);$('end').value=C.stamp(c.end);$('words').value=c.text;$('cueIssues').textContent=found.filter(x=>x.index===selected).map(x=>x.label).join(' · ')||'No automated review flags. Check the words against the recording.';$('merge').disabled=selected===state.cues.length-1;$('delete').disabled=state.cues.length===1;$('scrub').max=end;preview(+$('scrub').value);
}
function preview(ms){$('clock').textContent=C.stamp(ms);$('captionOverlay').textContent=state.cues.filter(c=>c.start<=ms&&c.end>ms).map(c=>c.text).join('\n');}
function name(ext){return (state.title.replace(/[^\p{L}\p{N}_-]/gu,'_').slice(0,80)||'captions')+'.'+ext;}
function download(text,filename,type){
 let old=$('exportDialog');if(old)old.remove();const dialog=document.createElement('dialog');dialog.id='exportDialog';const h=document.createElement('h2');h.textContent='Your file is ready';const p=document.createElement('p');p.textContent=filename+' — Download it, or select and copy the text below if downloads are blocked.';const area=document.createElement('textarea');area.value=text;area.rows=10;area.readOnly=true;area.setAttribute('aria-label','Exported file text');const actions=document.createElement('div');actions.className='actions';const a=document.createElement('a');a.className='button primary';a.textContent='Download file';a.download=filename;const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;const select=document.createElement('button');select.textContent='Select all text';select.onclick=()=>{area.focus();area.select();};const close=document.createElement('button');close.textContent='Close export';close.onclick=()=>dialog.close();actions.append(a,select,close);dialog.append(h,p,area,actions);dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.remove();});document.body.append(dialog);dialog.showModal();
}
function exportFull(format){if(dirty)throw Error('Save the current caption before exporting.');download(C.serialize(state.cues,format),name(format),'text/plain;charset=utf-8');notice(format.toUpperCase()+' is ready in the export window. Review it with your recording before publishing.');}
function clipInfo(){const a=C.time($('clipStart').value),b=C.time($('clipEnd').value),cues=C.clip(state.cues,a,b);if(!cues.length)throw Error('No captions fall inside this clip.');const trimmed=state.cues.filter(c=>c.end>a&&c.start<b&&(c.start<a||c.end>b)).length;return {a,b,cues,trimmed};}
function clipReview(){const x=clipInfo();$('clipSummary').textContent=((x.b-x.a)/1000).toFixed(2)+' seconds · '+x.cues.length+' captions\n'+(x.trimmed?x.trimmed+' boundary caption(s) shortened. Check for cut-off speech.\n':'Whole caption boundaries.\n')+'Opening: '+x.cues[0].text+'\nEnding: '+x.cues.at(-1).text;return x;}
function apply(){const cues=copy(state.cues);cues[selected]={start:C.time($('start').value),end:C.time($('end').value),text:$('words').value.replace(/\r/g,'').trim()};C.validate(cues);const target=cues[selected];cues.sort((a,b)=>a.start-b.start);selected=cues.indexOf(target);commit(cues,'Caption saved.');}
for(const id of ['start','end','words'])$(id).oninput=()=>dirty=true;
$('apply').onclick=()=>guard(apply);
$('wrap').onclick=()=>{$('words').value=C.wrap($('words').value,limits.line);dirty=true;notice('Lines wrapped. Save caption to keep the change. Long captions may still need splitting.');};
$('split').onclick=()=>guard(()=>{if(dirty)throw Error('Save your caption before splitting.');commit(C.split(state.cues,selected),'Caption split with estimated timing. Check the split against your recording.');});
$('merge').onclick=()=>guard(()=>{if(dirty)throw Error('Save your caption before merging.');commit(C.merge(state.cues,selected),'Merged with next caption. Review any silence between them.');});
$('delete').onclick=()=>guard(()=>{if(state.cues.length===1)throw Error('Keep at least one caption.');if(confirm('Delete caption '+(selected+1)+'?'))commit(state.cues.filter((_,i)=>i!==selected),'Caption deleted. Undo is available.');});
$('undo').onclick=()=>{if(!history.length||!discard())return;state=history.pop();selected=0;dirty=false;save();render();notice('Previous project state restored.');};
$('title').onchange=()=>{state.title=$('title').value.trim()||'Untitled captions';save();};
$('search').oninput=queue;$('onlyIssues').onchange=queue;
$('subFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Choose a subtitle file under 2 MB.');const p=C.parse(await f.text());replace({title:f.name.replace(/\.[^.]+$/,''),cues:p.cues},'Imported '+p.cues.length+' captions. '+p.warnings.join(' '));}catch(err){notice(err.message,true);}e.target.value='';};
$('demo').onclick=()=>replace({title:"Practice — The editor's promise",cues:copy(C.demo)},'Fictional practice example loaded. Try fixing caption 2’s overlap.');
$('backup').onclick=()=>guard(()=>{if(dirty)throw Error('Save your caption before backing up.');download(JSON.stringify(state,null,2),name('json'),'application/json');notice('Backup ready in the export window. Keep it to move your work to another device.');});
$('backupFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('Backup too large (maximum 3 MB).');replace(C.restore(await f.text()),'Backup restored. Reattach any local video to preview it.');}catch(err){notice(err.message,true);}e.target.value='';};
$('srt').onclick=()=>guard(()=>exportFull('srt'));$('vtt').onclick=()=>guard(()=>exportFull('vtt'));
$('clipPreview').onclick=()=>guard(clipReview);
$('clipSrt').onclick=()=>guard(()=>{if(dirty)throw Error('Save your caption before exporting.');const x=clipReview();download(C.serialize(x.cues),'clip_'+name('srt'),'text/plain;charset=utf-8');notice('Clip SRT ready. Trim your video to '+C.stamp(x.a)+'–'+C.stamp(x.b)+' in your editor.');});
$('markStart').onclick=()=>{$('clipStart').value=C.stamp(state.cues[selected].start);guard(clipReview);};$('markEnd').onclick=()=>{$('clipEnd').value=C.stamp(state.cues[selected].end);guard(clipReview);};
$('shift').onclick=()=>guard(()=>{if(dirty)throw Error('Save your caption before shifting.');if(!$('offset').value.trim())throw Error('Enter an offset in seconds.');const delta=Number($('offset').value)*1000;commit(C.shift(state.cues,delta),'All captions shifted by '+delta/1000+' seconds.');});
$('settings').onclick=()=>guard(()=>{const cps=+$('cps').value,line=+$('line').value;if(!Number.isFinite(cps)||cps<1||cps>100||!Number.isInteger(line)||line<10||line>100)throw Error('Use 1–100 characters/second and 10–100 characters/line.');if(!discard())return;limits={cps,line,min:800};dirty=false;render();notice('Review limits updated. These are editorial prompts, not mandatory rules.');});
$('report').onclick=()=>{const found=allIssues();download('# Caption Desk review\n\nProject: '+state.title+'\nGenerated: '+new Date().toISOString()+'\n\n'+state.cues.length+' captions. Review limits: '+limits.cps+' characters/sec; '+limits.line+' characters/line; 0.8 sec minimum. These are adjustable editorial prompts.\n\n'+(found.length?found.map(x=>'- Caption '+(x.index+1)+' ('+C.stamp(state.cues[x.index].start)+'): '+x.label).join('\n'):'No automated flags. This does not verify transcription accuracy.')+'\n\nCheck names, quoted references, negations and clip context against the recording.\n',name('md'),'text/markdown');};
$('videoFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(f);$('video').src=videoURL;$('video').hidden=false;$('previewEmpty').hidden=true;$('videoName').textContent=f.name+' · local playback only';notice('Local video attached. No file was uploaded by Caption Desk.');};
$('video').ontimeupdate=()=>{$('scrub').value=$('video').currentTime*1000;preview($('video').currentTime*1000);};$('video').onerror=()=>notice('This browser cannot play that media file. Use a compatible MP4/WebM or review it in your editor.',true);
$('scrub').oninput=()=>{const ms=+$('scrub').value;if(videoURL)$('video').currentTime=ms/1000;preview(ms);};$('aspect').onchange=()=>$('preview').classList.toggle('portrait',$('aspect').value==='portrait');
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
try{const raw=localStorage.getItem(key);if(raw){state={schema:'caption-desk/1',...C.restore(raw)};notice('Restored your last browser copy. Save a backup for safekeeping.');}}catch(e){notice('Could not restore a browser copy. The practice example is ready; you can open a JSON backup.',true);}
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'inspect_caption_project',title:'Inspect caption project',description:'Read the current subtitle counts, title, and timing/readability review flags without changing any data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return {title:state.title,count:state.cues.length,review:allIssues(),unsavedCaption:dirty};}})).catch(()=>{});}catch(e){}}

function renderBatch(){const parent=$('batchList');parent.replaceChildren();const clips=state.clips||[];$('batchExport').disabled=!clips.length;if(!clips.length){parent.textContent='No clips queued yet.';return;}clips.forEach((p,i)=>{const row=document.createElement('div');row.className='batch-row';const title=document.createElement('strong');title.textContent=(i+1)+'. '+p.name;const times=document.createElement('small');times.textContent=C.stamp(p.start)+' → '+C.stamp(p.end);const review=document.createElement('small');const cues=C.clip(state.cues,p.start,p.end);const cut=state.cues.filter(c=>c.end>p.start&&c.start<p.end&&(c.start<p.start||c.end>p.end)).length;review.textContent=cues.length+' captions · '+cut+' boundary trims'+(!cues.length?' — adjust range':'');const controls=document.createElement('div');controls.className='actions';const load=document.createElement('button');load.textContent='Review range';load.onclick=()=>{$('clipStart').value=C.stamp(p.start);$('clipEnd').value=C.stamp(p.end);$('batchName').value=p.name;guard(clipReview);$('clipStart').focus();};const remove=document.createElement('button');remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+p.name+' from batch');remove.onclick=()=>{history.push(copy(state));if(history.length>30)history.shift();state.clips.splice(i,1);save();renderBatch();$('undo').disabled=false;notice('Clip removed from batch. Undo is available.');};controls.append(load,remove);row.append(title,times,review,controls);parent.append(row);});}
$('batchAdd').onclick=()=>guard(()=>{if(dirty)throw Error('Save the current caption before adding a clip.');const clip=clipReview(),item={name:$('batchName').value.trim()||'Clip '+((state.clips||[]).length+1),start:clip.a,end:clip.b};const clips=[...(state.clips||[]),item];C.validateClips(clips);history.push(copy(state));if(history.length>30)history.shift();state.clips=clips;save();renderBatch();$('undo').disabled=false;$('batchName').value='';notice('Clip added. Set the next source range above, or download the batch.');});
$('batchExport').onclick=()=>guard(()=>{if(dirty)throw Error('Save the current caption before exporting.');const result=CaptionBatch.prepare(state.cues,state.clips||[],limits),dialog=document.createElement('dialog'),h=document.createElement('h2'),p=document.createElement('p'),a=document.createElement('a'),close=document.createElement('button');h.textContent='Your batch is ready';p.textContent=result.rows.length+' clips · SRT + VTT · '+result.rows.reduce((n,r)=>n+r.trimmed,0)+' boundary captions to check. Open clip-review.csv after extracting the ZIP.';a.className='button primary';a.textContent='Download ZIP';a.download=name('zip');const url=URL.createObjectURL(new Blob([result.bytes],{type:'application/zip'}));a.href=url;close.textContent='Close';close.onclick=()=>dialog.close();dialog.append(h,p,a,close);dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.remove();});document.body.append(dialog);dialog.showModal();notice('Batch created. Source captions and queued ranges are unchanged.');});
